 83	// Simple synthesized chimes (no audio assets needed). Per-event enable, like
 84	// the macOS SoundSettings (done = high glass-ish, waiting = lower submarine).
 85	let audioCtx: AudioContext | null = null;
 86	function chime(event: "done" | "waiting") {
 87	  const key = event === "done" ? "ap_sound_done" : "ap_sound_waiting";
 88	  const legacy = localStorage.getItem("ap_sound"); // pre-split toggle
 89	  const enabled = localStorage.getItem(key) ?? (legacy === "0" ? "0" : "1");
 90	  if (enabled === "0") return;
 91	  // Custom uploaded sound wins (mac SoundSettings custom file).
 92	  const data = localStorage.getItem(`ap_sound_${event}_data`);
 93	  if (data) {
 94	    try { void new Audio(data).play(); return; } catch {}
 95	  }
 96	  try {
 97	    audioCtx = audioCtx || new AudioContext();
 98	    const o = audioCtx.createOscillator();
 99	    const g = audioCtx.createGain();
100	    o.type = "sine";
101	    o.frequency.value = event === "done" ? 880 : 560;
102	    g.gain.value = 0.05;
103	    o.connect(g);
104	    g.connect(audioCtx.destination);
105	    o.start();
106	    o.stop(audioCtx.currentTime + 0.13);
107	  } catch {}
108	}
