110	// --- pick + load this instance's pet sprite -----------------------------------
111	function loadInstanceSprite() {
112	  const instance = myPetInstance();
113	  if (!instance) return;
114	  const url = libraryUrlForSlug(instance.spriteSlug)
115	    ?? (instance.id === "legacy-pet" ? localStorage.getItem("ap_pet_custom") || localStorage.getItem("ap_pet_url") : null);
