120	// --- mood + render loop --------------------------------------------------------
121	// Port of PetController: aggregate mood from the activity store, a 3s
122	// celebrate burst when entering done, a persistent idle line (re-picked on
123	// mood transitions, not blinking). Phase 1 has no activity producers yet, so
124	// the pet idles unless a celebrate/level-up flash is triggered (care feeds).
125	let celebrateUntil = 0;
126	let wasCelebrating = false;
127	let moodLine = ""; // the single-bubble line for idle/done/celebrate
128	let celebrateText = "";
