130	// Quick bubble: a short-lived message shown when the user clicks a pet or
131	// sends from the floating ball. Overrides the mood bubble for ~4s, then the
132	// normal render loop takes over again.
133	const QUICK_BUBBLE_MS = 4000;
134	const QUICK_KEY = "ap_quick_bubbles";
135	let quickBubbleText = "";
136	let quickBubbleUntil = 0;
137	
138	function readQuickPresets(): string[] {
139	  try {
140	    const v = JSON.parse(localStorage.getItem(QUICK_KEY) || "[]");
141	    return Array.isArray(v) ? v.filter((x: unknown) => typeof x === "string" && x.trim()) : [];
142	  } catch { return []; }
143	}
