145	  const list = readQuickPresets();
146	  if (!list.length) return null;
147	  return list[Math.floor(Math.random() * list.length)];
148	}
149	function showQuickBubble(text: string) {
150	  quickBubbleText = text;
151	  quickBubbleUntil = Date.now() + QUICK_BUBBLE_MS;
152	  render();
153	}
154	/// Play a celebrate burst with a custom line (achievement/level-up), then
155	/// settle back to the aggregate mood (mac PetController.flashCelebrate).
156	function flashCelebrate(line: string) {
157	  celebrateText = line;
158	  celebrateUntil = Date.now() + 3000;
159	  render();
160	}
