162	/// Feed this instance through a care mutation; on level-up plays a celebrate
163	/// burst in the same window.
164	export function feedPet(instanceId: string, change: (s: care.CareState) => void) {
165	  const before = care.stateFor(instanceId);
166	  const levelBefore = care.levelForXP(before.xp);
167	  care.mutate(instanceId, change);
168	  const after = care.stateFor(instanceId);
169	  emit("care-updated", { instanceId });
170	  const levelAfter = care.levelForXP(after.xp);
171	  if (levelAfter > levelBefore) {
172	    flashCelebrate(`${t("Level up")}! ${t("Lv")} ${care.displayLevel(after.xp)}`);
173	    chime("done");
174	  }
175	}
