177	function pickMoodLine(mood: string) {
178	  // Custom/system pools; working/waiting fall back to the PetChat lines so the
179	  // simple bubble always has something to say.
180	  let pool = bubbleLines(null, mood);
181	  if (!pool.length) pool = PET_CHAT[mood] ?? [];
182	  moodLine = pool.length ? pool[Math.floor(Math.random() * pool.length)] : "";
183	}
