185	// Render signature: when nothing changed, skip the DOM writes and IPC calls
186	// entirely. The 500ms timer keeps ticking but becomes a no-op while the pet is
187	// idle, instead of doing a full pass every tick.
188	let renderSig = "";
189	
190	function render() {
191	  const now = Date.now();
192	  // Quick bubble overrides everything for a few seconds after the user sends
193	  // a message from the floating ball or clicks the pet.
194	  if (now < quickBubbleUntil) {
195	    bubble.renderLine(quickBubbleText);
196	    snugBubble();
197	    reportHitRect();
198	    return;
199	  }
200	  const resolved = store.topState() === "done" ? "done" : "idle";
201	  const celebrating = now < celebrateUntil;
202	  const mood = celebrating ? "celebrate" : resolved;
203	  pet.setState(mood);
204	  setMood(mood);
205	  if (celebrating && wasCelebrating && now >= celebrateUntil) {
206	    // burst ended, settle into the actual mood's line
207	    pickMoodLine(resolved === "idle" ? "idle" : "done");
208	  }
209	  wasCelebrating = celebrating;
210	
211	  const sig = [mood, moodLine, celebrating ? celebrateText : ""].join("|");
212	  if (sig !== renderSig) {
213	    renderSig = sig;
214	    if (celebrating) {
215	      bubble.renderLine(celebrateText || t("Done"));
216	    } else if (resolved === "done") {
217	      if (!moodLine) pickMoodLine("done");
218	      bubble.renderLine(moodLine);
219	    } else if (localStorage.getItem("ap_idle") !== "0") {
220	      if (!moodLine) pickMoodLine("idle");
221	      bubble.renderLine(moodLine);
222	    } else {
223	      bubble.hide();
224	    }
225	  }
226	
227	  snugBubble();
228	  reportHitRect();
229	}
