248	// --- activity events ----------------------------------------------------------
249	// Activity integration is opt-in per desktop instance. The migrated legacy pet
250	// keeps its prior behavior; newly added pets remain independent until enabled.
251	listen<ActivityEventPayload>("activity-event", (e) => {
252	  const instance = myPetInstance();
253	  if (!instance?.reactsToActivity) return;
254	  store.apply(e.payload);
255	  if (e.payload.weight > 0) {
256	    if (e.payload.weight >= 0.5) {
257	      feedPet(instance.id, (state) => care.recordMeal(state, new Date(e.payload.timestamp)));
258	    } else {
259	      feedPet(instance.id, (state) => care.feedTokens(state, Math.max(1, Math.round(e.payload.weight * 10)) * 500, new Date(e.payload.timestamp)));
260	    }
261	  }
262	  render();
263	});
