289	// --- interactions ------------------------------------------------------------
290	// Drag works only when grabbing the PET SPRITE itself or the bubble, clicks
291	// on the transparent area beside the pet fall through (like the macOS panel,
292	// where transparent pixels never catch the mouse).
293	//
294	// Click vs drag: we don't startDragging on mousedown immediately. Instead we
295	// wait for the cursor to move > 4px, only then start the OS drag. If the
296	// mouse is released before moving, it's a click and we trigger a quick bubble
297	// (configurable via `ap_left_click_action`). This is necessary because Tauri's
298	// startDragging swallows the mouseup, so a `click` event never fires.
299	const LEFT_CLICK_KEY = "ap_left_click_action";
300	let pendingDrag = false;
301	let downX = 0;
302	let downY = 0;
303	
304	function onPetClick() {
305	  const action = (localStorage.getItem(LEFT_CLICK_KEY) || "none") as "none" | "self" | "all";
306	  if (action === "none") return;
307	  const text = randomPreset();
308	  if (!text) return;
309	  if (action === "self") {
