316	canvas.addEventListener("mousedown", (e) => {
317	  if (e.button !== 0) return;
318	  // While the sheet is still loading there is no sprite rect yet, allow the
319	  // drag anyway so the pet is never untouchable.
320	  if (pet.spriteRect && !pet.hitTest(e.offsetX, e.offsetY)) return;
321	  emit("popover-close", null);
322	  pendingDrag = true;
323	  downX = e.screenX;
324	  downY = e.screenY;
325	});
326	window.addEventListener("mousemove", (e) => {
327	  if (!pendingDrag) return;
328	  if (Math.abs(e.screenX - downX) <= 4 && Math.abs(e.screenY - downY) <= 4) return;
329	  pendingDrag = false;
330	  setDragging(true);
331	  getCurrentWindow().startDragging().finally(() => setDragging(false));
332	});
333	window.addEventListener("mouseup", () => {
334	  if (!pendingDrag) return;
335	  pendingDrag = false;
336	  onPetClick();
337	});
338	bubbleEl.addEventListener("mousedown", async (e) => {
339	  if (e.button !== 0) return;
340	  emit("popover-close", null);
341	  setDragging(true);
342	  try {
343	    await getCurrentWindow().startDragging();
344	  } finally {
