399	// Respect the in-app / OS reduced-motion preference on transparent pet windows.
400	function applyReduceMotion() {
401	  document.body.classList.toggle("reduce-motion", localStorage.getItem("ap_reduce_motion") === "1");
402	}
403	applyReduceMotion();
404	window.addEventListener("storage", (e) => { if (e.key === "ap_reduce_motion") applyReduceMotion(); });
