 56	let sleeping = false;
 57	
 58	/// Moods that freeze the pet so the bubble / celebration animation stays readable.
 59	const MOOD_PAUSES_ROAM = new Set(["waiting", "celebrate"]);
 60	
 61	function stop(): boolean { return stopRequested; }
 62	
 63	/// Called from main.ts after each mood evaluation. Non-idle moods wake the pet.
 64	export function setMood(m: string): void {
 65	  mood = m;
 66	  if (m !== "idle") wake();
 67	}
 68	
 69	function wake(): void {
 70	  if (!sleeping) return;
 71	  sleeping = false;
 72	  petRef?.clearRow();
 73	}
 74	
 75	function enterSleep(): void {
 76	  if (sleeping) return;
 77	  sleeping = true;
 78	  const bound = parseInt(localStorage.getItem("ap_bind_sleep") ?? "", 10);
 79	  const row = Number.isFinite(bound) && bound >= 0 ? bound : SLEEP_ROW_DEFAULT;
 80	  petRef?.setRow(row);
 81	}
 82	
 83	/// One engine tick. Priority: throw > drag-sample > drag-release > mood-pause > sleep > mode.
 84	/// Returns true when the pet is actively moving/interacting and needs the fast
 85	/// (30ms) tick; false when resting/sleeping/stationary so the loop can use the
 86	/// idle (200ms) tick and skip most IPC calls.
 87	async function tick(): Promise<boolean> {
 88	  if (isThrowing()) return true;
 89	  if (dragging) {
 90	    const pos = await currentLogicalPos();
 91	    if (pos) recordSample(pos);
 92	    return true;
 93	  }
 94	  if (releasePending) {
 95	    releasePending = false;
 96	    const vel = releaseVelocity();
 97	    clearSamples();
 98	    if (vel && Math.hypot(vel.vx, vel.vy) > THROW_MIN_SPEED) {
 99	      wake();
100	      await handleDragRelease(vel);
101	      return true;
102	    }
103	  }
104	
105	  // Mood-driven freeze: keep the pet still while the user needs to see the
106	  // bubble or the celebrate burst. Throws and drags above still work.
107	  if (MOOD_PAUSES_ROAM.has(mood)) {
108	    wake();
109	    petRef?.clearRow();
110	    return false;
111	  }
112	
113	  const cfg = loadConfig();
114	  if (!cfg.enabled || cfg.mode === "stay") {
115	    handleStationary();
116	    return false;
117	  }
118	
119	  wake();
120	  const moved = await stepMode(cfg.mode);
121	  if (!moved && mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
122	    enterSleep();
123	  }
124	  return moved;
125	}
126	
127	/// Run one mode step and apply it. Returns true if the pet actually moved.
128	async function stepMode(mode: RoamMode): Promise<boolean> {
129	  const env = await fetchEnvironment(mode === "climb");
130	  if (!env) { diag(`env=null mode=${mode}`); return false; }
131	  const pos = await currentLogicalPos();
132	  if (!pos) { diag(`pos=null mode=${mode}`); return false; }
133	
134	  const next = await runMode(mode, { env, pos, pet: petRef });
135	  const clamped = clampToBounds(next, env.workArea);
136	  const moved = Math.abs(clamped.x - pos.x) >= 0.5 || Math.abs(clamped.y - pos.y) >= 0.5;
137	  diag(`mode=${mode} win=${env.windows.length} pos=(${pos.x.toFixed(0)},${pos.y.toFixed(0)}) next=(${next.x.toFixed(0)},${next.y.toFixed(0)}) moved=${moved}`);
138	  if (!moved) {
139	    return false;
140	  }
141	  lastMoveTs = Date.now();
142	  try { await setLogical(clamped); }
143	  catch (e) { void invoke("log_debug", { msg: `roam: setPosition error: ${e}` }).catch(() => {}); }
144	  return true;
145	}
146	
147	/// Pet is stationary (mode is stay or roaming disabled): maybe doze off.
148	function handleStationary(): void {
149	  if (mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
150	    enterSleep();
151	  } else {
152	    wake();
153	    petRef?.clearRow();
154	  }
155	}
156	
157	type ReleaseContext = {
158	  config: Config;
159	  environment: Environment;
160	};
161	
162	type ConfigReader = () => Config;
163	type EnvironmentReader = (includeSystemWindows: boolean) => Promise<Environment | null>;
164	
165	export async function resolveReleaseContext(
166	  getConfig: ConfigReader = loadConfig,
167	  getEnvironment: EnvironmentReader = fetchEnvironment,
168	): Promise<ReleaseContext | null> {
169	  let config = getConfig();
170	  const includedSystemWindows = config.mode === "climb";
171	  let environment = await getEnvironment(includedSystemWindows);
172	  if (!environment) return null;
173	
174	  config = getConfig();
175	  if (config.mode === "climb" && !includedSystemWindows) {
176	    environment = await getEnvironment(true);
177	    if (!environment) return null;
178	  }
179	
180	  return { config: getConfig(), environment };
181	}
182	
183	async function handleDragRelease(vel: { vx: number; vy: number }): Promise<void> {
184	  const context = await resolveReleaseContext();
185	  if (!context) return;
186	  const { config: cfg, environment: env } = context;
187	
188	  if (cfg.mode === "climb" && env.windows.length > 0) {
189	    const surfaces = env.windows.map((w) => w.rect);
190	    await applyFall(vel.vx, env.workArea, surfaces, petRef, stop);
191	  } else {
192	    await applyThrow(vel.vx, vel.vy, env.workArea, petRef, stop);
193	  }
194	}
195	
196	async function loop(): Promise<void> {
197	  while (!stopRequested) {
198	    const active = await tick();
199	    await sleep(active ? TICK_MS : IDLE_TICK_MS);
200	  }
201	  petRef?.clearRow();
202	}
203	
204	export function initEngine(pet: Pet): void {
205	  if (petRef) return;
206	  petRef = pet;
207	  stopRequested = false;
208	  lastMoveTs = Date.now();
209	  mood = "idle";
210	  sleeping = false;
211	  void loop();
212	}
213	
214	export function destroyEngine(): void {
215	  stopRequested = true;
216	  cancelThrow();
217	  petRef = null;
218	}
219	
220	export function setDragging(isDragging: boolean): void {
221	  dragging = isDragging;
222	  setNativeDragTracking(isDragging);
223	  if (isDragging) {
224	    cancelThrow();
225	    clearSamples();
226	    wake();
227	    releasePending = false;
228	  } else if (petRef) {
229	    releasePending = true;
230	  }
231	}

