  8	export type FloatingBallDragHost = {
  9	  cursorPosition(): Promise<PhysicalPoint>;
 10	  setPosition(position: PhysicalPoint): Promise<void>;
 11	  persistPosition(): Promise<void>;
 12	};
 13	
 14	export type FloatingBallDragOutcome = {
 15	  kind: "click" | "drag" | "cancel";
 16	  completion: Promise<void> | null;
 17	};
 18	
 19	type ActiveDrag = {
 20	  pointerId: number;
 21	  startPoint: Point;
 22	  latestPoint: Point;
 23	  grabOffset: PhysicalPoint;
 24	  startedAt: number;
 25	  isDragging: boolean;
 26	  needsMove: boolean;
 27	  moveTask: Promise<void> | null;
 28	  firstMoveError: unknown | null;
 29	};
 30	
 31	export class FloatingBallDragController {
 32	  private active: ActiveDrag | null = null;
 33	
 34	  constructor(
 35	    private readonly host: FloatingBallDragHost,
 36	    private readonly thresholdPx = 4,
 37	    private readonly clickMaxMs = 280,
 38	  ) {}
 39	
 40	  get isDragging(): boolean {
 41	    return this.active?.isDragging ?? false;
 42	  }
 43	
 44	  begin(pointerId: number, point: Point, grabOffset: PhysicalPoint, startedAt: number): boolean {
 45	    if (this.active) return false;
 46	    this.active = {
 47	      pointerId,
 48	      startPoint: point,
 49	      latestPoint: point,
 50	      grabOffset,
 51	      startedAt,
 52	      isDragging: false,
 53	      needsMove: false,
 54	      moveTask: null,
 55	      firstMoveError: null,
 56	    };
 57	    return true;
 58	  }
 59	
 60	  move(pointerId: number, point: Point): boolean {
 61	    const drag = this.active;
 62	    if (!drag || drag.pointerId !== pointerId) return false;
 63	    drag.latestPoint = point;
 64	    if (!drag.isDragging && this.movedBeyondThreshold(drag)) {
 65	      this.start(drag);
 66	      return true;
 67	    }
 68	    if (drag.isDragging) this.queueMove(drag);
 69	    return false;
 70	  }
 71	
 72	  finish(
 73	    pointerId: number,
 74	    point: Point,
 75	    allowClick: boolean,
 76	    now: number,
 77	  ): FloatingBallDragOutcome | null {
 78	    const drag = this.active;
 79	    if (!drag || drag.pointerId !== pointerId) return null;
 80	
 81	    drag.latestPoint = point;
 82	    this.active = null;
 83	    if (!drag.isDragging && this.movedBeyondThreshold(drag)) this.start(drag);
 84	    if (!drag.isDragging) {
 85	      return {
 86	        kind: allowClick && now - drag.startedAt <= this.clickMaxMs ? "click" : "cancel",
 87	        completion: null,
 88	      };
 89	    }
 90	
 91	    this.queueMove(drag);
 92	    return { kind: "drag", completion: this.persistAfterFinalMove(drag) };
 93	  }
 94	
 95	  private movedBeyondThreshold(drag: ActiveDrag): boolean {
 96	    return Math.abs(drag.latestPoint.x - drag.startPoint.x) > this.thresholdPx
 97	      || Math.abs(drag.latestPoint.y - drag.startPoint.y) > this.thresholdPx;
 98	  }
 99	
100	  private start(drag: ActiveDrag): void {
101	    drag.isDragging = true;
102	    this.queueMove(drag);
103	  }
104	
105	  private queueMove(drag: ActiveDrag): void {
106	    drag.needsMove = true;
107	    if (drag.moveTask) return;
108	
109	    const task = this.moveToLatestCursorPosition(drag);
110	    drag.moveTask = task;
111	    void task.then(
112	      () => { if (drag.moveTask === task) drag.moveTask = null; },
113	      (error) => {
114	        if (drag.firstMoveError === null) drag.firstMoveError = error;
115	        if (drag.moveTask === task) drag.moveTask = null;
116	      },
117	    );
118	  }
119	
120	  private async moveToLatestCursorPosition(drag: ActiveDrag): Promise<void> {
121	    while (drag.needsMove) {
122	      drag.needsMove = false;
123	      const cursor = await this.host.cursorPosition();
124	      await this.host.setPosition({
125	        x: cursor.x - drag.grabOffset.x,
126	        y: cursor.y - drag.grabOffset.y,
127	      });
128	    }
129	  }
130	
131	  private async persistAfterFinalMove(drag: ActiveDrag): Promise<void> {
132	    const finalMove = drag.moveTask;
133	    if (finalMove) await finalMove;
134	    await this.host.persistPosition();
135	    if (drag.firstMoveError !== null) throw drag.firstMoveError;
136	  }
137	}

