 61	  btn.textContent = line;
 62	  btn.title = t("Send to selected") + " · " + t("Shift-click to delete");
 63	  btn.onclick = (ev) => {
 64	    if (ev.shiftKey) {
 65	      const next = readPresets().filter((_, j) => j !== index);
 66	      writePresets(next);
 67	      selectedPreset = -1;
 68	      paintPresets();
 69	      syncSend();
 70	      return;
 71	    }
 72	    selectedPreset = index;
 73	    input.value = line;
 74	    paintPresets();
