108	/// Height delta between the menu window and the ball window.
109	const MENU_GROW = MENU_H - WIN_SIZE;
110	
111	async function showMenu() {
112	  if (!menu.hidden) return;
113	  input.value = "";
114	  selectedPreset = -1;
115	  paintPresets();
116	  syncSend();
117	
118	  const pos = await win.outerPosition();
119	  const sf = await win.scaleFactor();
120	  const mon = await currentMonitor();
121	  const work = mon?.workArea;
122	  const logicalX = pos.x / sf;
123	  const logicalY = pos.y / sf;
124	  const workLeft = work ? work.position.x / sf : logicalX;
125	  const workTop = work ? work.position.y / sf : logicalY;
126	  const workRight = work ? (work.position.x + work.size.width) / sf : logicalX + MENU_W;
127	  const workBottom = work ? (work.position.y + work.size.height) / sf : logicalY + MENU_H;
128	
129	  // If the menu would overflow the bottom, open UPWARD: the ball sticks to
130	  // the bottom of the window and the menu sits above it. The window's Y
131	  // moves up by MENU_GROW so the ball's screen position is preserved.
132	  const openAbove = logicalY + MENU_H > workBottom;
133	  // Adjust X so the wider menu window stays on-screen.
134	  let newX = logicalX;
135	  if (newX + MENU_W > workRight) newX = workRight - MENU_W;
136	  if (newX < workLeft) newX = workLeft;
137	  let newY = logicalY;
138	  if (openAbove) newY = logicalY - MENU_GROW;
139	  // Clamp Y so the window never starts above the work area.
140	  if (newY < workTop) newY = workTop;
141	
142	  document.body.classList.toggle("menu-above", openAbove);
143	  if (Math.abs(newX - logicalX) > 0.5 || Math.abs(newY - logicalY) > 0.5) {
144	    void win.setPosition(new LogicalPosition(newX, newY));
145	  }
146	  // Resize FIRST, then reveal the menu, so the menu never appears clipped
147	  // inside the still-80×80 window for a frame.
148	  await win.setSize(new LogicalSize(MENU_W, MENU_H));
149	  menu.hidden = false;
150	  requestAnimationFrame(() => input.focus());
151	}
152	
153	function hideMenu() {
154	  if (menu.hidden) return;
155	  menu.hidden = true;
156	  const wasAbove = document.body.classList.contains("menu-above");
157	  document.body.classList.remove("menu-above");
158	  shrinkToBall();
159	  if (wasAbove) {
160	    // Window was shifted up by MENU_GROW to open the menu above.
161	    // Move it back down so the ball returns to its original screen position.
162	    void (async () => {
163	      const pos = await win.outerPosition();
164	      const sf = await win.scaleFactor();
165	      void win.setPosition(new LogicalPosition(pos.x / sf, pos.y / sf + MENU_GROW));
166	    })();
167	  }
168	}
