  2	
  3	type Point = { x: number; y: number };
  4	type DragOutcome = {
  5	  kind: "click" | "drag" | "cancel";
  6	  completion: Promise<void> | null;
  7	};
  8	type DragController = {
  9	  begin(pointerId: number, point: Point, grabOffset: Point, startedAt: number): boolean;
 10	  move(pointerId: number, point: Point): boolean;
 11	  finish(pointerId: number, point: Point, allowClick: boolean, now: number): DragOutcome | null;
 12	};
 13	type PointerOptions = {
 14	  drag: DragController;
 15	  isMenuOpen(): boolean;
 16	  hideMenu(): void;
 17	  showMenu(): void;
 18	  now(): number;
 19	  scale(): number;
 20	  reportError(error: unknown): void;
 21	};
 22	type PointerModule = {
 23	  attachFloatingBallPointerDrag(ball: HTMLElement, options: PointerOptions): void;
 24	};
 25	
 26	const pointerModulePath = "./floating-ball-pointer";
 27	
 28	async function attach(ball: FakeBall, options: PointerOptions): Promise<void> {
 29	  const module = await import(/* @vite-ignore */ pointerModulePath).catch(() => null);
 30	  expect(module).not.toBeNull();
 31	  (module as PointerModule).attachFloatingBallPointerDrag(ball as unknown as HTMLElement, options);
 32	}
