 34	class FakeBall {
 35	  readonly captured = new Set<number>();
 36	  readonly classes = new Set<string>();
 37	  private readonly listeners = new Map<string, (event: PointerEvent) => void>();
 38	
 39	  readonly classList = {
 40	    add: (...names: string[]) => names.forEach((name) => this.classes.add(name)),
 41	    remove: (...names: string[]) => names.forEach((name) => this.classes.delete(name)),
 42	  };
 43	
 44	  addEventListener(type: string, listener: (event: PointerEvent) => void): void {
 45	    this.listeners.set(type, listener);
 46	  }
 47	
 48	  setPointerCapture(pointerId: number): void {
 49	    this.captured.add(pointerId);
 50	  }
 51	
 52	  hasPointerCapture(pointerId: number): boolean {
 53	    return this.captured.has(pointerId);
 54	  }
 55	
 56	  releasePointerCapture(pointerId: number): void {
 57	    this.captured.delete(pointerId);
 58	  }
 59	
 60	  dispatch(type: string, event: PointerEvent): void {
 61	    this.listeners.get(type)?.(event);
 62	  }
 63	}
 64	
 65	function pointerEvent(overrides: Partial<PointerEvent> = {}): PointerEvent {
 66	  return {
 67	    pointerId: 1,
 68	    button: 0,
 69	    screenX: 100,
 70	    screenY: 200,
 71	    clientX: 10,
 72	    clientY: 20,
 73	    preventDefault: vi.fn(),
 74	    ...overrides,
 75	  } as PointerEvent;
 76	}
 77	
 78	function options(drag: DragController, overrides: Partial<PointerOptions> = {}): PointerOptions {
 79	  return {
 80	    drag,
 81	    isMenuOpen: vi.fn().mockReturnValue(false),
 82	    hideMenu: vi.fn(),
 83	    showMenu: vi.fn(),
 84	    now: vi.fn().mockReturnValue(500),
 85	    scale: vi.fn().mockReturnValue(1.5),
 86	    reportError: vi.fn(),
 87	    ...overrides,
 88	  };
 89	}
 90	
 91	describe("floating ball pointer binding", () => {
 92	  it("captures a pointer, starts dragging, then releases it without duplicate completion", async () => {
 93	    const drag: DragController = {
 94	      begin: vi.fn().mockReturnValue(true),
 95	      move: vi.fn().mockReturnValue(true),
 96	      finish: vi.fn().mockReturnValue({ kind: "click", completion: null }),
 97	    };
 98	    const ball = new FakeBall();
 99	    const config = options(drag);
100	    await attach(ball, config);
101	
102	    const down = pointerEvent();
103	    ball.dispatch("pointerdown", down);
104	    expect(down.preventDefault).toHaveBeenCalledTimes(1);
105	    expect(drag.begin).toHaveBeenCalledWith(1, { x: 100, y: 200 }, { x: 15, y: 30 }, 500);
106	    expect(ball.captured).toContain(1);
107	    expect(ball.classes).toContain("pressed");
108	
109	    ball.dispatch("pointermove", pointerEvent({ screenX: 110 }));
110	    expect(drag.move).toHaveBeenCalledWith(1, { x: 110, y: 200 });
111	    expect(ball.classes).not.toContain("pressed");
112	    expect(ball.classes).toContain("dragging");
113	
114	    ball.dispatch("pointerup", pointerEvent({ screenX: 120 }));
115	    expect(drag.finish).toHaveBeenCalledWith(1, { x: 120, y: 200 }, true, 500);
116	    expect(config.showMenu).toHaveBeenCalledTimes(1);
117	    expect(ball.captured).not.toContain(1);
118	    expect(ball.classes).not.toContain("dragging");
119	
120	    ball.dispatch("lostpointercapture", pointerEvent({ screenX: 120 }));
121	    expect(drag.finish).toHaveBeenCalledTimes(1);
122	  });
123	
124	  it("cancels a drag without opening the menu and reports asynchronous failures", async () => {
125	    const failure = new Error("persist failed");
126	    const completion = Promise.reject(failure);
127	    void completion.catch(() => {});
128	    const drag: DragController = {
129	      begin: vi.fn().mockReturnValue(true),
130	      move: vi.fn().mockReturnValue(false),
131	      finish: vi.fn().mockReturnValue({ kind: "drag", completion }),
132	    };
133	    const ball = new FakeBall();
134	    const config = options(drag);
135	    await attach(ball, config);
136	
137	    ball.dispatch("pointerdown", pointerEvent({ pointerId: 2 }));
138	    ball.dispatch("pointercancel", pointerEvent({ pointerId: 2, screenX: 140 }));
139	
140	    expect(drag.finish).toHaveBeenCalledWith(2, { x: 140, y: 200 }, false, 500);
141	    expect(config.showMenu).not.toHaveBeenCalled();
142	    expect(ball.captured).not.toContain(2);
143	    await vi.waitFor(() => expect(config.reportError).toHaveBeenCalledWith(failure));
144	  });
145	
146	  it("closes an open menu instead of beginning a new drag", async () => {
147	    const drag: DragController = {
148	      begin: vi.fn().mockReturnValue(true),
149	      move: vi.fn().mockReturnValue(false),
150	      finish: vi.fn().mockReturnValue(null),
151	    };
152	    const ball = new FakeBall();
153	    const config = options(drag, { isMenuOpen: vi.fn().mockReturnValue(true) });
154	    await attach(ball, config);
155	
156	    ball.dispatch("pointerdown", pointerEvent());
157	
158	    expect(config.hideMenu).toHaveBeenCalledTimes(1);
159	    expect(drag.begin).not.toHaveBeenCalled();
160	    expect(ball.captured).toHaveLength(0);
161	  });
162	});

