  6	import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
  7	import { runMode } from "./modes";
  8	import type { Environment, Point } from "./types";
  9	import { clampToBounds } from "./types";
 10	
 11	vi.mock("@tauri-apps/api/window", () => ({
 12	  cursorPosition: vi.fn(),
 13	}));
 14	
 15	let storedRoamMode = "climb";
 16	vi.stubGlobal("localStorage", {
 17	  getItem: vi.fn((key: string) => (key === "ap_roam_mode" ? storedRoamMode : null)),
 18	});
 19	
 20	const pet = { clearRow: vi.fn(), setRow: vi.fn() };
 21	
 22	function mulberry32(seed: number) {
 23	  let a = seed >>> 0;
 24	  return () => {
 25	    a |= 0; a = (a + 0x6d2b79f5) | 0;
 26	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
 27	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
 28	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
 29	  };
 30	}
 31	
 32	const WORK_AREA = { left: 0, top: 0, right: 1920, bottom: 1040 };
 33	
 34	/// Mirrors engine.stepMode: clamp, then treat <0.5px movement as stationary.
 35	async function stepMode(env: Environment, pos: Point): Promise<{ next: Point; moved: boolean }> {
 36	  const next = await runMode("climb", { env, pos, pet: pet as never });
 37	  const clamped = clampToBounds(next, env.workArea);
 38	  const moved = Math.abs(clamped.x - pos.x) >= 0.5 || Math.abs(clamped.y - pos.y) >= 0.5;
 39	  return { next: clamped, moved };
 40	}
 41	
 42	async function simulateEngine(env: Environment, start: Point, ticks = 900): Promise<boolean> {
 43	  let pos = start;
 44	  let stallRun = 0;
 45	  let finalStuck = false;
 46	  const t0 = Date.now();
 47	  await runMode("wander", { env, pos, pet: pet as never }); // reset module state
 48	  const rng = mulberry32(7777);
 49	  const spy = vi.spyOn(Math, "random").mockImplementation(rng);
 50	  try {
 51	    for (let i = 0; i < ticks; i++) {
 52	      // real loop sleeps 30ms when moving, 200ms when stationary
 53	      vi.setSystemTime(t0 + i * (stallRun > 0 ? 200 : 30));
 54	      const { next, moved } = await stepMode(env, pos);
 55	      stallRun = moved ? 0 : stallRun + 1;
 56	      // stationary for the final ~9s (resting pauses are <= 3.5s) => stuck
 57	      if (i > ticks - 300 && stallRun > 60) finalStuck = true;
 58	      pos = next;
 59	    }
 60	  } finally {
 61	    spy.mockRestore();
 62	  }
 63	  return finalStuck;
 64	}
 65	
 66	function randomWindow(rnd: () => number, i: number): Environment["windows"][number] {
 67	  const w = 300 + rnd() * 1400;
 68	  const h = 200 + rnd() * 700;
 69	  const top = Math.round((rnd() - 0.35) * 1600);
 70	  const left = Math.round((rnd() - 0.2) * 2100);
 71	  return { title: `W${i}`, rect: { left, top, right: left + w, bottom: top + h } };
 72	}
 73	
 74	describe("engine-level climb never gets permanently stuck", () => {
 75	  beforeEach(() => {
 76	    vi.useFakeTimers();
 77	    vi.setSystemTime(new Date(2025, 0, 1));
 78	  });
 79	  afterEach(() => {
 80	    vi.useRealTimers();
 81	  });
 82	
 83	  it("random layouts x random starts (300 seeds, full tick loop)", async () => {
 84	    const stuck: Array<{ seed: number; start: Point; windows: unknown }> = [];
 85	    for (let seed = 0; seed < 300; seed++) {
 86	      const rnd = mulberry32(seed);
 87	      const nWin = 1 + Math.floor(rnd() * 5);
 88	      const windows = Array.from({ length: nWin }, (_, i) => randomWindow(rnd, i));
 89	      const env: Environment = { workArea: WORK_AREA, windows };
 90	      const start: Point = {
 91	        x: Math.round(rnd() * 1800),
 92	        y: Math.round(rnd() * 900),
 93	      };
 94	      const stuckNow = await simulateEngine(env, start, 900);
 95	      if (stuckNow) {
 96	        stuck.push({ seed, start, windows });
 97	        if (stuck.length >= 5) break;
 98	      }
 99	    }
100	    expect(stuck).toEqual([]);
101	  }, 60_000);
102	});

