 19	/// The pet's opaque region in physical pixels, relative to the window's top-left.
 20	/// The frontend reports this (canvas + visible bubble) so the background thread
 21	/// can make the transparent rest of the window click-through.
 22	#[derive(Default, Clone)]
 23	#[cfg_attr(not(windows), allow(dead_code))]
 24	struct HitRect {
 25	    x: f64,
 26	    y: f64,
 27	    w: f64,
 28	    h: f64,
 29	}
 30	
 31	/// Per-window hit rects: every persistent desktop-pet window reports its own
 32	/// opaque rect so the click-through loop can handle them independently.
 33	type HitRectMap = std::collections::HashMap<String, HitRect>;
 34	
 35	const PET_WINDOW_PREFIX: &str = "pet-";
 36	const MAX_DESKTOP_PETS: usize = 12;
 37	type PetPositionMap = std::collections::HashMap<String, (i32, i32)>;
 38	
 39	#[derive(Default)]
 40	struct DesktopPetSyncState {
 41	    generation: u64,
 42	}
 43	
 44	#[derive(Clone, Deserialize)]
 45	#[serde(rename_all = "camelCase")]
 46	struct DesktopPetWindow {
 47	    id: String,
 48	    visible: bool,
 49	}
 50	
 51	fn is_pet_window(label: &str) -> bool {
 52	    label.starts_with(PET_WINDOW_PREFIX)
 53	}
 54	
 55	fn apply_ignore_state<E>(
 56	    last_ignore: &mut std::collections::HashMap<String, bool>,
 57	    label: &str,
 58	    ignore: bool,
 59	    set_ignore: impl FnOnce(bool) -> Result<(), E>,
 60	) -> bool {
 61	    if last_ignore.get(label) == Some(&ignore) || set_ignore(ignore).is_err() {
 62	        return false;
 63	    }
 64	    last_ignore.insert(label.to_owned(), ignore);
 65	    true
 66	}
 67	
 68	fn pet_window_label(id: &str) -> String {
 69	    format!("{PET_WINDOW_PREFIX}{id}")
 70	}
 71	
 72	fn valid_pet_id(id: &str) -> bool {
 73	    !id.is_empty()
 74	        && id.len() <= 64
 75	        && id.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
 76	}
 77	
 78	fn pet_positions_file() -> Option<std::path::PathBuf> {
 79	    dirs::config_dir().map(|d| d.join("DesktopPet").join("pet-positions.json"))
 80	}
 81	
 82	fn read_pet_positions() -> PetPositionMap {
 83	    let Some(path) = pet_positions_file() else { return PetPositionMap::new() };
 84	    let Ok(raw) = std::fs::read_to_string(path) else { return PetPositionMap::new() };
 85	    serde_json::from_str(&raw).unwrap_or_default()
 86	}
 87	
 88	fn write_pet_positions(positions: &PetPositionMap) {
 89	    let Some(path) = pet_positions_file() else { return };
 90	    if let Some(parent) = path.parent() {
 91	        let _ = std::fs::create_dir_all(parent);
 92	    }
 93	    if let Ok(raw) = serde_json::to_string(positions) {
 94	        let _ = std::fs::write(path, raw);
 95	    }
 96	}
