 98	fn desktop_pets_visible_file() -> Option<std::path::PathBuf> {
 99	    dirs::config_dir().map(|d| d.join("DesktopPet").join("pets-visible"))
100	}
101	
102	fn read_desktop_pets_visible() -> bool {
103	    desktop_pets_visible_file()
104	        .and_then(|path| std::fs::read_to_string(path).ok())
105	        .map(|value| value.trim() != "0")
106	        .unwrap_or(true)
107	}
108	
109	fn write_desktop_pets_visible(visible: bool) {
110	    if let Some(path) = desktop_pets_visible_file() {
111	        if let Some(parent) = path.parent() {
112	            let _ = std::fs::create_dir_all(parent);
113	        }
114	        let _ = std::fs::write(path, if visible { "1" } else { "0" });
115	    }
116	}
