285	fn build_desktop_pet_window(
286	    app: &tauri::AppHandle,
287	    instance: &DesktopPetWindow,
288	    index: usize,
289	) -> Result<(), String> {
290	    let label = pet_window_label(&instance.id);
291	    if let Some(window) = app.get_webview_window(&label) {
292	        if instance.visible && read_desktop_pets_visible() {
293	            window.show().map_err(|error| error.to_string())?;
294	        } else {
295	            window.hide().map_err(|error| error.to_string())?;
296	        }
297	        return Ok(());
298	    }
299	
300	    let url = format!("index.html?pet={}", instance.id);
301	    let mut builder = WebviewWindowBuilder::new(app, &label, WebviewUrl::App(url.into()))
302	        .title("DesktopPet")
303	        .inner_size(260.0, 320.0)
304	        .transparent(true)
305	        .decorations(false)
306	        .always_on_top(true)
307	        .skip_taskbar(true)
308	        .resizable(false)
309	        .shadow(false)
310	        .focused(false)
311	        .visible(instance.visible && read_desktop_pets_visible());
312	    builder = match saved_pet_position(app, &instance.id) {
313	        Some((x, y)) => {
314	            let (x, y) = logical_position_for_physical(app, x, y);
315	            builder.position(x, y)
316	        }
317	        None => {
318	            let (x, y) = default_pet_position(app, index);
319	            builder.position(x, y)
320	        }
321	    };
322	    builder.build().map_err(|error| error.to_string())?;
323	    Ok(())
324	}
