326	fn sync_desktop_pet_windows_impl(app: tauri::AppHandle, pets: Vec<DesktopPetWindow>) {
327	    use std::collections::HashSet;
328	    let wanted: HashSet<String> = pets.iter().map(|pet| pet_window_label(&pet.id)).collect();
329	    for (label, window) in app.webview_windows() {
330	        if is_pet_window(&label) && !wanted.contains(&label) {
331	            let _ = window.close();
332	        }
333	    }
334	    for (index, pet) in pets.iter().enumerate() {
335	        if let Err(error) = build_desktop_pet_window(&app, pet, index) {
336	            dlog(&format!("desktop pet window failed for {}: {error}", pet.id));
337	        }
338	    }
339	}
