341	/// Reconciles every persistent desktop-pet instance with a single frontend
342	/// source of truth. Window labels are opaque IDs, never sprite slugs or projects.
343	#[tauri::command]
344	async fn sync_desktop_pet_windows(
345	    app: tauri::AppHandle,
346	    pets: Vec<DesktopPetWindow>,
347	) -> Result<(), String> {
348	    if pets.len() > MAX_DESKTOP_PETS {
349	        return Err(format!("desktop pet limit is {MAX_DESKTOP_PETS}"));
350	    }
351	    let mut ids = std::collections::HashSet::new();
352	    for pet in &pets {
353	        if !valid_pet_id(&pet.id) || !ids.insert(&pet.id) {
354	            return Err("invalid or duplicate desktop pet id".into());
355	        }
356	    }
357	    let generation = app
358	        .try_state::<Mutex<DesktopPetSyncState>>()
359	        .and_then(|state| state.lock().ok().map(|mut state| {
360	            state.generation = state.generation.wrapping_add(1);
361	            state.generation
362	        }))
363	        .ok_or("desktop pet sync state unavailable")?;
364	    std::thread::spawn(move || {
365	        let is_current = app
366	            .try_state::<Mutex<DesktopPetSyncState>>()
367	            .and_then(|state| state.lock().ok().map(|state| state.generation == generation))
368	            .unwrap_or(false);
369	        if is_current {
370	            sync_desktop_pet_windows_impl(app, pets);
371	        }
372	    });
373	    Ok(())
374	}
