376	/// The floating ball window label. A single instance lives on the desktop as a
377	/// stable click target (left = bubble menu, right = Settings) so the user
378	/// doesn't have to chase a roaming pet.
379	const FLOATING_BALL_LABEL: &str = "floating-ball";
380	// The visible orb is 56×56, but the window is 80×80 so shadows and hover
381	// scale are not clipped by the square window edges.
382	const BALL_W: f64 = 80.0;
383	const BALL_H: f64 = 80.0;
384	
385	fn ball_pos_file() -> Option<std::path::PathBuf> {
386	    dirs::config_dir().map(|d| d.join("DesktopPet").join("ball-pos"))
387	}
388	fn read_ball_pos() -> Option<(f64, f64)> {
389	    let s = std::fs::read_to_string(ball_pos_file()?).ok()?;
390	    let (a, b) = s.trim().split_once(',')?;
391	    Some((a.trim().parse().ok()?, b.trim().parse().ok()?))
392	}
393	fn write_ball_pos(x: f64, y: f64) {
394	    if let Some(p) = ball_pos_file() {
395	        if let Some(d) = p.parent() { let _ = std::fs::create_dir_all(d); }
396	        let _ = std::fs::write(p, format!("{x},{y}"));
397	    }
398	}
399	fn ball_visible_file() -> Option<std::path::PathBuf> {
400	    dirs::config_dir().map(|d| d.join("DesktopPet").join("ball-visible"))
401	}
402	fn read_ball_visible() -> bool {
403	    ball_visible_file()
404	        .and_then(|p| std::fs::read_to_string(p).ok())
405	        .map(|s| s.trim() != "0")
406	        .unwrap_or(true)
407	}
408	fn write_ball_visible(on: bool) {
409	    if let Some(p) = ball_visible_file() {
410	        if let Some(d) = p.parent() { let _ = std::fs::create_dir_all(d); }
411	        let _ = std::fs::write(p, if on { "1" } else { "0" });
412	    }
