415	/// Spawn the floating ball window if it doesn't exist yet. Position is restored
416	/// from disk (clamped onto a monitor) or defaulted to the bottom-right corner.
417	/// Must be called from a worker thread, like open_settings_impl.
418	fn spawn_floating_ball_impl(app: tauri::AppHandle) {
419	    if app.get_webview_window(FLOATING_BALL_LABEL).is_some() {
420	        return;
421	    }
422	    let (sw, sh) = primary_work_area(&app);
423	    let (x, y) = read_ball_pos()
424	        .filter(|&(x, y)| x >= 0.0 && x <= sw && y >= 0.0 && y <= sh)
425	        .unwrap_or_else(|| (sw - BALL_W - 24.0, sh - BALL_H - 80.0));
426	    let _ = WebviewWindowBuilder::new(
427	        &app,
428	        FLOATING_BALL_LABEL,
429	        WebviewUrl::App("floating-ball.html".into()),
430	    )
431	    .title("DesktopPet")
432	    .inner_size(BALL_W, BALL_H)
433	    .position(x.max(0.0), y.max(0.0))
434	    .transparent(true)
435	    .decorations(false)
436	    .always_on_top(true)
437	    .skip_taskbar(true)
438	    .resizable(false)
439	    .shadow(false)
440	    .focused(false)
441	    .build();
442	}
