444	/// Persist the floating ball's drop position after an OS-level drag.
445	/// This deliberately avoids a second set_position call, which can flash on
446	/// Windows transparent windows during the drag-end compositor update.
447	#[tauri::command]
448	fn persist_floating_ball_position(app: tauri::AppHandle) {
449	    let Some(win) = app.get_webview_window(FLOATING_BALL_LABEL) else {
450	        return;
451	    };
452	    let Ok(pos) = win.outer_position() else {
453	        return;
454	    };
455	    let Ok(scale_factor) = win.scale_factor() else {
456	        return;
457	    };
458	    write_ball_pos(pos.x as f64 / scale_factor, pos.y as f64 / scale_factor);
459	}
